begin;
create extension if not exists pgtap with schema extensions;
set search_path = public, private, extensions;
select plan(11);
insert into public.workspaces(id) values ('b9999999-9999-4999-8999-999999999991');
select private.record_external_provider_cost('b9999999-9999-4999-8999-999999999991','cs35','b9999999-9999-4999-8999-999999999992','apify','run1','facebook',0.126,'2026-07-01','2026-08-01');
select private.record_external_provider_cost('b9999999-9999-4999-8999-999999999991','cs35','b9999999-9999-4999-8999-999999999992','apify','run1','facebook',0.126,'2026-07-01','2026-08-01');
select is((select count(*)::int from private.external_provider_costs where app_id='cs35'),1,'retry does not duplicate a run');
select private.record_external_provider_cost('b9999999-9999-4999-8999-999999999991','cs35','b9999999-9999-4999-8999-999999999992','apify','run1','facebook',0.2,'2026-07-01','2026-08-02');
select is((select amount_usd from private.external_provider_costs where app_id='cs35'),0.2::numeric,'newer observation corrects the total');
select private.record_external_provider_cost('b9999999-9999-4999-8999-999999999991','cs35','b9999999-9999-4999-8999-999999999992','apify','run1','facebook',0.1,'2026-07-01','2026-08-01');
select is((select amount_usd from private.external_provider_costs where app_id='cs35'),0.2::numeric,'late retry cannot replace a correction');
select is((select month from private.get_external_provider_costs('b9999999-9999-4999-8999-999999999991','2026-07-01','2026-08-01')),'2026-07','aggregation uses historical run month');
select is((select count(*)::int from private.get_external_provider_costs('b9999999-9999-4999-8999-999999999992','2026-07-01','2026-08-01')),0,'other workspace sees no costs');
select ok(not has_table_privilege('authenticated','private.external_provider_costs','SELECT'),'authenticated cannot bypass API permission checks');
select ok(not has_function_privilege('anon','private.record_external_provider_cost(uuid,text,uuid,text,text,text,numeric,timestamptz,timestamptz,text,text)','EXECUTE'),'anonymous cannot ingest');
select ok(has_function_privilege('service_role','private.record_external_provider_cost(uuid,text,uuid,text,text,text,numeric,timestamptz,timestamptz,text,text)','EXECUTE'),'service role can ingest');
select throws_ok($$select private.record_external_provider_cost('b9999999-9999-4999-8999-999999999991','cs35','b9999999-9999-4999-8999-999999999992','apify','run2','facebook',-1,'2026-07-01','2026-08-01')$$,'23514',null,'negative amounts rejected');
select private.record_external_provider_cost('b9999999-9999-4999-8999-999999999991','cs35','b9999999-9999-4999-8999-999999999992','apify','account-day','account_usage',0.5,'2026-07-01','2026-08-03','account1','account_day');
select is((select sum(amount_usd) from private.get_external_provider_costs('b9999999-9999-4999-8999-999999999991','2026-07-01','2026-08-01')),0.5::numeric,'account day replaces covered run cost instead of double counting');
select is((select count(*)::int from private.external_provider_costs where app_id='cs35'),2,'run detail remains available for audit');
select * from finish();
rollback;
